import { LocalizedText } from './components/common/LocalizedText';
import React, { useEffect, useRef, useState } from 'react';
import { BrowserRouter as Router, Navigate, useLocation, useNavigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import { ToastProvider } from './context/ToastContext';
import { LanguageProvider } from './context/LanguageContext';
import { Header } from './components/layout/Header';
import { MinimalAuthHeader } from './components/layout/MinimalAuthHeader';
import { Footer } from './components/layout/Footer';
import { AiTravelCompanionDrawer } from './components/ai/AiTravelCompanionDrawer';
import { AppRoutes } from './routes/AppRoutes';
import { getHomeRouteForRole } from './utils/navigation';
import { ThemeProvider } from './context/ThemeContext';

const AppContent: React.FC = () => {
  const { user, loading } = useAuth();
  const [aiDrawerOpen, setAiDrawerOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();
  const [sessionReady, setSessionReady] = useState(false);
  const restored = useRef(false);

  useEffect(() => {
    if (loading || restored.current) return;
    restored.current = true;
    if (user) navigate(getHomeRouteForRole(user), { replace: true });
    setSessionReady(true);
  }, [loading, user, navigate]);

  const pathname = location.pathname;
  const isAuthRoute = pathname === '/login' || pathname === '/register';

  // Restore the session before deciding whether sign-in is required.
  if (loading || !sessionReady) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-cream text-brand-brown" role="status"><LocalizedText text={" Loading SETU... "} /></div>
    );
  }

  if (!user && !isAuthRoute) {
    return <Navigate to="/login" replace />;
  }

  let bgImage = '/tourist.jpeg';
  if (pathname.startsWith('/vendor')) {
    bgImage = '/vendor.jpeg';
  } else if (isAuthRoute) {
    bgImage = '/login.jpeg';
  }

  return (
    <div
      className="min-h-screen flex flex-col justify-between font-serif bg-cover bg-center bg-fixed transition-all duration-700"
      style={{ backgroundImage: `url('${bgImage}')` }}
    >
      {isAuthRoute ? (
        <MinimalAuthHeader />
      ) : (
        <Header onOpenAi={() => setAiDrawerOpen(true)} />
      )}
      <main className="flex-grow">
        <AppRoutes />
      </main>
      <Footer />
      <AiTravelCompanionDrawer
        isOpen={aiDrawerOpen}
        onClose={() => setAiDrawerOpen(false)}
      />
    </div>
  );
};

export const App: React.FC = () => {
  return (
    <LanguageProvider>
      <ThemeProvider>
      <AuthProvider>
        <ToastProvider>
          <Router>
            <AppContent />
          </Router>
        </ToastProvider>
      </AuthProvider>
      </ThemeProvider>
    </LanguageProvider>
  );
};

export default App;
